// Simulate camera detection results for demo purposes
var rnd = new Random();

// --- Entrance camera (YOLO enabled by default) ---
if (ReadBool("Cameras.Entrance.YoloEnabled"))
{
    var labels = new[] { "person", "car", "bicycle", "dog", "backpack", "truck" };
    var pick = labels[rnd.Next(labels.Length)];
    var conf = 0.4 + rnd.NextDouble() * 0.55; // 0.40 – 0.95
    var count = rnd.Next(0, 6);
    Write("Detection.Entrance.Label", count > 0 ? pick : "");
    Write("Detection.Entrance.Confidence", count > 0 ? Math.Round(conf, 4) : 0.0);
    Write("Detection.Entrance.Count", count);
    Write("Detection.Entrance.Alive", true);

    if (pick == "person") Write("Stats.TotalPeopleDetected", ReadInt("Stats.TotalPeopleDetected") + count);
    if (pick == "car" || pick == "truck") Write("Stats.TotalVehiclesDetected", ReadInt("Stats.TotalVehiclesDetected") + count);
}
else
{
    Write("Detection.Entrance.Alive", false);
}

// --- Warehouse camera ---
if (ReadBool("Cameras.Warehouse.YoloEnabled"))
{
    var wLabels = new[] { "person", "forklift", "box", "pallet", "truck" };
    var wPick = wLabels[rnd.Next(wLabels.Length)];
    var wConf = 0.35 + rnd.NextDouble() * 0.6;
    var wCount = rnd.Next(0, 4);
    Write("Detection.Warehouse.Label", wCount > 0 ? wPick : "");
    Write("Detection.Warehouse.Confidence", wCount > 0 ? Math.Round(wConf, 4) : 0.0);
    Write("Detection.Warehouse.Count", wCount);
    Write("Detection.Warehouse.Alive", true);
}
else
{
    Write("Detection.Warehouse.Alive", false);
}

// --- Parking lot camera ---
if (ReadBool("Cameras.ParkingLot.YoloEnabled"))
{
    var pLabels = new[] { "car", "truck", "motorcycle", "person", "bicycle" };
    var pPick = pLabels[rnd.Next(pLabels.Length)];
    var pConf = 0.5 + rnd.NextDouble() * 0.45;
    var pCount = rnd.Next(0, 8);
    Write("Detection.ParkingLot.Label", pCount > 0 ? pPick : "");
    Write("Detection.ParkingLot.Confidence", pCount > 0 ? Math.Round(pConf, 4) : 0.0);
    Write("Detection.ParkingLot.Count", pCount);
    Write("Detection.ParkingLot.Alive", true);

    if (pPick == "car" || pPick == "truck" || pPick == "motorcycle") Write("Stats.TotalVehiclesDetected", ReadInt("Stats.TotalVehiclesDetected") + pCount);
    if (pPick == "person") Write("Stats.TotalPeopleDetected", ReadInt("Stats.TotalPeopleDetected") + pCount);
}
else
{
    Write("Detection.ParkingLot.Alive", false);
}

// Active camera count
int active = 0;
if (ReadBool("Cameras.Entrance.YoloEnabled")) active++;
if (ReadBool("Cameras.Warehouse.YoloEnabled")) active++;
if (ReadBool("Cameras.ParkingLot.YoloEnabled")) active++;
Write("Stats.ActiveCameras", active);
